// Everything is in the mapping table. Council and batch are stated twice in its
// path, and each case's file is named absolutely in its local-path columns, so
// the directory to walk is derived from those rather than typed again -- a
// second answer to a question the table already answers is a second chance to
// answer it wrong, and it would fail halfway through disassembly.
const text = key => String($json[key] || '').trim();
const mapping_table = text('mapping_table');
// One model reads the batch. The pipeline can run PP-OCR over everything and
// the VLM over what it scored unclear, but then the same page has two answers
// and nothing records which engine produced which.
const engine = (text('engine') || 'ppocr-v6').toLowerCase();

if (!mapping_table) throw new Error('Mapping table is required.');
if (!mapping_table.startsWith('/data/') || mapping_table.includes('/../') || mapping_table.startsWith('/data/file-browser-data')) {
  throw new Error('Mapping table must be a safe path below /data and outside /data/file-browser-data.');
}
if (!/-full-mapping\.(csv|xlsx)$/.test(mapping_table)) {
  throw new Error('The mapping table must be the 20-column total table, <council>-<batch>-full-mapping.csv. The slim table carries no confidence and no local download path.');
}
if (!['ppocr-v6', 'ppocr-v5', 'vlm'].includes(engine)) {
  throw new Error('OCR model must be ppocr-v6, ppocr-v5 or vlm.');
}

return [{json:{mapping_table, engine}}];

// What the run is, before any of it has happened. The adapted row count is the
// number that matters: a mapping table lists every case, and only the ones with
// a local download can be preprocessed.
const r = $json;
const t = r.input_table || {};
return [{json:{
  run_id: r.run_id,
  work_dir: r.work_dir,
  council: r.council,
  batch: r.batch,
  engine: r.engine,
  vlm: r.vlm,
  raw_input: r.raw_input,
  scan_root: r.scan_root,
  cases_to_process: t.rows,
  checked: $('Inputs usable').first().json,
  cases_in_mapping_table: t.rows_in_mapping_table,
  cases_without_local_download: t.rows_without_local_download,
  cases_from_portal: t.rows_from_portal,
  log: r.log,
  poll: 0,
}}];

// The end of the chain. A finished run that produced no OCR rows did not merely
// stop early -- it produced nothing, and the bridge reports that as failed
// rather than completed.
const s = $json;
const start = $('Started').first().json;
const c = s.counts || {};
return [{json:{
  status: 'preprocessed',
  run_id: s.run_id,
  council: s.council,
  batch: s.batch,
  engine: s.engine,
  work_dir: s.work_dir,
  cases_to_process: start.cases_to_process,
  cases_in_mapping_table: start.cases_in_mapping_table,
  cases_without_local_download: start.cases_without_local_download,
  cases_from_portal: start.cases_from_portal,
  summary_rows: c.summary_rows,
  detail_rows: c.detail_rows,
  ocr_rows: c.ocr_rows,
  outputs: s.outputs,
  // One row per case, including the ones that produced nothing. The pipeline
  // counts images and never records which case an image came from, so a case
  // that downloaded files and produced no page is invisible in every total it
  // reports. by_status is where that shows.
  case_log: s.case_log,
}}];

// Neither running nor finished with output. The run directory holds everything
// it did manage, and the pipeline resumes from its own sidecars, so this is a
// pause rather than a loss: starting again with skip_existing continues from
// the last finished image.
const s = $json;
const c = s.counts || {};
return [{json:{
  status: s.state === 'failed' ? 'pipeline_failed' : 'still_running_after_budget',
  run_id: s.run_id,
  work_dir: s.work_dir,
  state: s.state,
  ocr_rows: c.ocr_rows,
  summary_rows: c.summary_rows,
  log_tail: s.log_tail,
  resume_with: {work_dir: s.work_dir, skip_existing: true},
  outputs: s.outputs,
  case_log: s.case_log,
}}];

// A batch that is half downloaded is a real state, so this reports counts and
// only stops when there is nothing to work on. The numbers travel with the run:
// a batch that shrinks between mapping and OCR is the failure worth catching,
// and it can only be seen by comparing what the table listed with what was read.
const c = $json;
const cases = c.cases || {};
if (!c.ready) {
  throw new Error(`${c.mapping_table} cannot be preprocessed: ${(c.reasons || []).join('; ')}`);
}
return [{json:{
  mapping_table: c.mapping_table,
  engine: $('Validate request').first().json.engine,
  council: c.council,
  batch: c.batch,
  cases_in_table: cases.in_table,
  cases_with_local_path: cases.with_local_path,
  cases_without_local_path: cases.without_local_path,
  cases_from_portal: cases.from_portal,
  local_file_present: cases.local_file_present,
  local_file_missing: cases.local_file_missing,
  missing_examples: c.missing_examples || [],
}}];
